/* ============================================================================
   TERANOVA - BACK END / APP LOGIC
   ----------------------------------------------------------------------------
   All of the app's logic and its data layer live here: state, storage, device
   control, energy simulation, bill calculations, plans, account and settings.
   No markup and no styling.
   Load it from teranova-frontend.html, which defines the element IDs it uses
   (#home, #pwr, #devices, #plan, #bills, #learn, #account, #nav, ...).

   Storage: state is kept in the browser's localStorage under the keys
   "tera", "tera_notices" and "tera_rgrp". Nothing is sent to a server.
   To run this against a real server, replace the store.get / store.set
   helpers at the top of the file with your own API calls.
   ============================================================================ */

const $=s=>document.querySelector(s);
const J=n=>"J$"+Math.round(n).toLocaleString("en-US");
const store={get(k,d){try{const v=localStorage.getItem(k);return v?JSON.parse(v):d}catch(e){return d}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch(e){}}};

const DEF=[{k:"lights",n:"Lights",w:0,cmd:"L"},{k:"pump",n:"Water pump",w:0,cmd:"P"},{k:"fan",n:"Fan",w:0,cmd:"F"},{k:"heater",n:"Solar water heater",w:0,cmd:"H"}];
const DEV=[];
const S=Object.assign({relays:{},lock:false,rate:68,paired:{},tab:"home",live:null,src:"",cfg:{preset:"generic",url:"",solar:"",load:"",battery:"",grid:"",k:{solar:1,load:1,grid:1},kw:false,poll:5},
  battery:0,solar:0,load:0,grid:0,kwhSolar:0,kwhGrid:0,hasBat:false,
  history:[],
  elec:{prev:0,cur:0,rate:68,fixed:0},water:{prev:0,cur:0,rate:310,fixed:0},
  bills:[]},store.get("yaad",{}));

(S.cdevs||[]).forEach(d=>{if(!DEV.find(x=>x.k===d.k)){DEV.push(d);if(S.relays[d.k]==null)S.relays[d.k]=false}});
(S.gone||[]).forEach(k=>{const i=DEV.findIndex(d=>d.k===k);if(i>=0)DEV.splice(i,1)});
if(!S.btns)S.btns=DEV.filter(d=>!d.custom).map(d=>({id:"b_"+d.k,name:d.n,sys:d.k==="pump"?"water":"appliances",devs:[d.k]}));
S.btns=S.btns.map(b=>({...b,devs:b.devs.filter(id=>DEV.find(d=>d.k===id))})).filter(b=>b.devs.length);
if(!S.rooms)S.rooms={};
function save(){store.set("yaad",{relays:S.relays,lock:S.lock,rate:S.rate,paired:S.paired,cfg:S.cfg,btns:S.btns,cdevs:DEV,gone:S.gone,rooms:S.rooms,elec:S.elec,water:S.water,bills:S.bills})}

function sim(){
  if(S.live&&Date.now()-S.live.ts<60000&&(S.live.solar!=null||S.live.load!=null)){live();return}
  if(S.src)return;
  const h=new Date().getHours()+new Date().getMinutes()/60;
  const sun=h>6&&h<18.5?Math.sin((h-6)/12.5*Math.PI):0;
  S.solar=Math.max(0,Math.round(sun*1800*(0.9+Math.random()*0.2)));
  S.load=180+DEV.reduce((a,d)=>a+(S.relays[d.k]?d.w:0),0);
  const net=S.solar-S.load;
  if(net>0&&S.battery<100){S.battery=Math.min(100,S.battery+0.15);S.grid=0}
  else if(net<0&&S.battery>15){S.battery=Math.max(15,S.battery-0.12);S.grid=0}
  else S.grid=Math.max(0,-net);
  const f=2/3600/1000;
  const fromSolar=Math.min(S.load,S.solar+(net<0&&S.battery>15?-net:0));
  S.kwhSolar+=fromSolar*f;S.kwhGrid+=S.grid*f;
}

function icon(p){return `<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${p}</svg>`}
const TABS=[["home","Home",'<path d="M3 11l9-8 9 8M5 10v10h14V10"/>'],["pwr","Power",'<path d="M13 2L4 14h7l-1 8 9-12h-7z"/>'],["plan","Your plan",'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="4"/>'],["bills","Bills",'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 8h6M9 12h6M9 16h4"/>'],["account","Account",'<circle cx="12" cy="8" r="4"/><path d="M4 21c0-4 4-6 8-6s8 2 8 6"/>']];
function nav(){$("#nav").innerHTML=TABS.map(t=>`<button data-t="${t[0]}" class="${S.tab===t[0]?"on":""}">${icon(t[2])}${t[1]}</button>`).join("");
  document.querySelectorAll("nav button").forEach(b=>b.onclick=()=>{if(b.dataset.t==="devices")S.folder=null;go(b.dataset.t)});pill()}
function go(t){const M={connect:"solar"};if(M[t]){S.folder=M[t];t="devices"}
 S.tab=t;document.querySelectorAll("main section").forEach(s=>s.classList.toggle("on",s.id===t));nav();render();window.scrollTo(0,0)}

function pct(a,b){return b?Math.round(a/b*100):0}
function homeBase(){
 
 const p=P(),used=Math.max(S.load,1),sol=Math.min(S.solar,used),bat=S.solar<used&&S.battery>15&&S.grid===0?used-sol:0,grid=Math.max(0,used-sol-bat),tot=S.kwhSolar+S.kwhGrid;
 const tr=p?(()=>{const dl=Math.max(0,Math.ceil((new Date(p.trialEnds)-Date.now())/864e5));return `<div class="trial"><b>Welcome, ${T(p.name)}</b>Your free trial of the paid version has ${dl} days left.</div>`})():"";
 $("#home").innerHTML=`${tr}
 <div class="hero"><div style="opacity:.85">Your ${p&&p.place&&p.place!=="home"?"property is":"home is"} using</div>
  <div class="big">${S.load}<span> watts</span></div>
  <div class="flow"><i style="width:${pct(sol,used)}%;background:var(--sun)"></i><i style="width:${pct(bat,used)}%;background:#7fe3a2"></i><i style="width:${pct(grid,used)}%;background:#cfd8cb"></i></div>
  <div class="legend"><span><b style="background:var(--sun)"></b>Solar ${sol} W</span><span><b style="background:#7fe3a2"></b>Battery ${Math.round(bat)} W</span><span><b style="background:#cfd8cb"></b>Grid ${Math.round(grid)} W</span></div>${S.src?"":`<div style="opacity:.85;font-size:13px;margin-top:8px">Demo readings until you connect a source.</div>`}</div>
 ${upcoming(p)}
 <div class="grid2">
  <div class="stat"><div class="mute">Battery</div><div class="v">${S.hasBat?Math.round(S.battery)+"%":"—"}</div></div>
  <div class="stat"><div class="mute">Solar today</div><div class="v">${pct(S.kwhSolar,tot)}%</div></div>
  <div class="stat"><div class="mute">Used today</div><div class="v">${tot.toFixed(1)} kWh</div></div>
  <div class="stat"><div class="mute">Cost today</div><div class="v">${J(S.kwhGrid*S.rate)}</div></div></div>
 <div class="card" style="margin-top:12px"><h2>Tip for today</h2><p style="margin:0">${S.solar>S.load?"Solar is covering your whole load. Run the water pump now to store water on free power.":"Solar is low. Switch off the water heater backup to avoid grid power."}</p></div>`;
 document.querySelectorAll("[data-nd]").forEach(b=>b.onclick=()=>{store.set("yaad_notices",notices().filter(n=>String(n.id)!==b.dataset.nd));home()});
 const ns=$("#ns");if(ns)ns.onclick=()=>{const d=$("#nd").value;if(!d)return;store.set("yaad_notices",notices().concat({id:Date.now(),t:$("#nt").value,d,n:$("#nn").value.trim()}));home()};
}
function chart(vals,labels){
  const w=320,h=120,m=Math.max(...vals)*1.15,bw=w/vals.length;
  return `<svg viewBox="0 0 ${w} ${h+22}" width="100%" role="img" aria-label="Daily energy use in kWh">${vals.map((v,i)=>{const bh=v/m*h;return `<rect x="${i*bw+8}" y="${h-bh}" width="${bw-16}" height="${bh}" rx="5" fill="${i===vals.length-1?"var(--green)":"var(--gold)"}"/><text x="${i*bw+bw/2}" y="${h-bh-4}" text-anchor="middle" font-size="11" fill="var(--ink)">${v.toFixed(1)}</text><text x="${i*bw+bw/2}" y="${h+15}" text-anchor="middle" font-size="11" fill="var(--mute)">${labels[i]}</text>`}).join("")}</svg>`;
}
function power(){
  const tot=S.kwhSolar+S.kwhGrid,days=["Fri","Sat","Sun","Mon","Tue","Today"],hist=S.history.slice(0,5).concat([tot]);
  const month=(hist.reduce((a,b)=>a+b,0)/hist.length)*30;
  $("#power").innerHTML=`
  <div class="card"><h2>Energy today</h2><div class="grid2">
   <div><div class="mute">Total</div><div class="v" style="font-size:28px;font-weight:800">${tot.toFixed(1)} kWh</div></div>
   <div><div class="mute">Grid cost</div><div class="v" style="font-size:28px;font-weight:800">${J(S.kwhGrid*S.rate)}</div></div></div>
   <label for="rt">Your electricity rate (J$ per kWh, from your bill)</label><input id="rt" type="number" min="0" value="${S.rate}"></div>
  <div class="card"><h2>Energy mix</h2>
   <div class="flow" style="background:var(--line)"><i style="width:${pct(S.kwhSolar,tot)}%;background:var(--sun)"></i><i style="width:${pct(S.kwhGrid,tot)}%;background:var(--grid)"></i></div>
   <div class="legend" style="color:var(--ink)"><span><b style="background:var(--sun)"></b>Solar ${S.kwhSolar.toFixed(1)} kWh</span><span><b style="background:var(--grid)"></b>Grid ${S.kwhGrid.toFixed(1)} kWh</span></div>
   <p class="mute">${S.hasBat?"Battery "+Math.round(S.battery)+"%, "+(S.battery>15?"discharging only when solar is short":"at reserve level")+". ":""}Grid power in Jamaica includes Wigton wind (62.7 MW).</p></div>
  <div class="card"><h2>Daily energy</h2>${chart(hist,days.slice(6-hist.length))}
   <p class="mute" style="margin-bottom:0">Projected this month: ${month.toFixed(0)} kWh, about ${J(month*S.rate*(1-pct(S.kwhSolar,tot)/100))} if the solar share holds.</p></div>`;
  $("#rt").onchange=e=>{S.rate=+e.target.value||0;S.elec.rate=S.rate;save();power()};
}
function billsBase(){
  const e=S.elec,w=S.water,ec=Math.max(0,e.cur-e.prev),wc=Math.max(0,w.cur-w.prev);
  const eb=ec*e.rate+e.fixed,wb=wc*w.rate+w.fixed;
  const f=(o,k,l,u)=>`<div><label for="${o}${k}">${l}</label><input id="${o}${k}" type="number" min="0" data-o="${o}" data-k="${k}" value="${S[o][k]}"></div>`;
  $("#bills").innerHTML=`
  <div class="card"><h2>Electricity bill</h2><div class="two">${f("elec","prev","Last reading (kWh)")}${f("elec","cur","Current reading (kWh)")}${f("elec","rate","Rate (J$/kWh)")}${f("elec","fixed","Fixed charges (J$)")}</div>
   <div class="row"><span>${ec||e.cur?ec+" kWh used":"Enter your meter readings"}</span><b style="font-size:20px">${J(eb)}</b></div><button data-s="Electricity" data-a="${eb}">Save this bill</button></div>
  <div class="card"><h2>Water bill</h2><div class="two">${f("water","prev","Last reading (m³)")}${f("water","cur","Current reading (m³)")}${f("water","rate","Rate (J$/m³)")}${f("water","fixed","Fixed charges (J$)")}</div>
   <div class="row"><span>${wc||w.cur?wc+" m³ used":"Enter your meter readings"}</span><b style="font-size:20px">${J(wb)}</b></div><button data-s="Water" data-a="${wb}">Save this bill</button></div>
  <div class="card"><h2>Bill history</h2>${S.bills.length?S.bills.map(b=>`<div class="bill"><div><h3>${b.t}</h3><span class="mute">${b.m}</span></div><div><b>${J(b.amt)}</b> <button class="alt tag ${b.paid?"paid":""}" data-pay="${b.id}" style="padding:3px 9px;border-width:0">${b.paid?"Paid":"Mark paid"}</button></div></div>`).join(""):'<p class="mute">No bills saved yet. Enter your readings above and save.</p>'}
   <p class="mute" style="margin-bottom:0">Rates are editable. Copy them from your latest JPS and NWC bills; they are not fetched live.</p></div>`;
  document.querySelectorAll("[data-o]").forEach(i=>i.onchange=()=>{S[i.dataset.o][i.dataset.k]=+i.value||0;save();bills()});
  document.querySelectorAll("[data-s]").forEach(b=>b.onclick=()=>{const m=new Date().toLocaleString("en-US",{month:"long"});S.bills.unshift({id:Date.now(),t:b.dataset.s,m,amt:Math.round(+b.dataset.a),paid:false});save();bills()});
  document.querySelectorAll("[data-pay]").forEach(b=>b.onclick=()=>{const x=S.bills.find(y=>y.id==b.dataset.pay);x.paid=!x.paid;save();bills()});
}
const Q=[["Which project is the $65M Palisadoes investment mainly about?",["Wind power","Coastal development and road resilience","Mangrove nurseries"],1],
["Costa Rica raised forest cover by paying landowners. What is this called?",["Payment for ecosystem services","A carbon tax","Zoning"],0],
["About how many Barbados households use solar water heaters?",["4%","40%","90%"],1]];
let qi=0,qs=0;
