function yCmd(c){if(!Y.chara)return Promise.resolve(false);Y.q=(Y.q||Promise.resolve()).then(async()=>{try{await Y.chara.writeValue(new TextEncoder().encode(c));return true}catch(e){Y.status="Command failed: "+e.message;yRender();return false}});return Y.q}
