 el.querySelectorAll("[data-rm]").forEach(i=>i.onchange=()=>{const v=i.value.trim(),k=i.dataset.rm;if(v)S.rooms[k]=v;else delete S.rooms[k];save()});
 el.querySelectorAll("[data-wt]").forEach(i=>i.onchange=()=>{const d=dvOf(i.dataset.wt),v=parseFloat(i.value);if(d&&!isNaN(v)&&v>=0){d.w=v;save()}});
 const ap=$("#addPreset");if(ap)ap.onclick=()=>{DEF.forEach(d=>{if(!dvOf(d.k)){DEV.push({...d});S.relays[d.k]=false;if(!S.btns.find(x=>x.id==="b_"+d.k))S.btns.push({id:"b_"+d.k,name:d.n,sys:d.k==="pump"?"water":"appliances",devs:[d.k]})}});save();panel()};
