function wcls(w){return w>=1000?"hi":w>=300?"mid":"lo"}
function actW(d,i){if(!S.relays[d.k])return 0;const nom=DEV.filter(x=>S.relays[x.k]).reduce((a,x)=>a+x.w,0)||1;if(S.src&&S.load>0)return Math.round(d.w*S.load/nom);const t=Date.now();return Math.round(d.w*(1+0.08*Math.sin(t/9000+i)+((i%3===2&&Math.sin(t/60000)>0.3)?0.35:0)))}
