function why(n){n=n.toLowerCase();return /heat/.test(n)?["Thermostat set too high or scale build-up.","Lower the setting and descale it."]:/fan|ac|hvac|air/.test(n)?["Dirty filter or blocked airflow.","Clean the filter and keep doors closed."]:/fridge|freez|refrig/.test(n)?["Worn door seal or dusty coils.","Check the seal, clean the coils and keep it away from heat."]:/pump/.test(n)?["Running dry, or a leak keeps it working.","Check for leaks and use a float switch."]:["It is drawing more than its usual rating or was left running.","Switch it off when idle and have it checked."]}
