  const rows=rn.map((r,ri)=>{const it=rs[r],rk=gk+"r"+ri,rt=it.reduce((a,x)=>a+actW(x[0],x[1]),0),ro=it.filter(x=>S.relays[x[0].k]).length,ropen=S.openU[rk];
   return `<div class="sub"><div class="gh"><button class="gx" data-x="${rk}" aria-expanded="${!!ropen}">${ropen?"\u25BE":"\u25B8"} ${T(r)}</button><span class="rd ${it.some(x=>bad.has(x[0].k))?"hi":wcls(rt)}">${rt} W</span>${sw(`data-ks="${it.map(x=>x[0].k).join(",")}"`,ro===it.length,T(r))}</div><div ${ropen?"":"hidden"}><div class="gh" style="margin:6px 0 4px"><input data-rn="${rk}" type="text" maxlength="40" value="${T(r)}" aria-label="Room name" style="flex:1"><button class="alt" data-rs="${rk}" data-rks="${it.map(x=>x[0].k).join(",")}" style="width:auto;padding:8px 14px">Rename</button></div><p class="err" id="re_${rk}" role="alert" style="margin:0 0 6px"></p>${it.map(x=>{const d=x[0],w=actW(d,x[1]);return `<div class="row"><div><h3>${T(d.n)}${bad.has(d.k)?" "+cau:""}</h3><span class="rd ${wcls(w)}">${w} W</span>${bad.has(d.k)?` <span class="mute">High power use</span>`:""}</div>${sw(`data-dv="${d.k}"`,S.relays[d.k],T(d.n))}</div>`}).join("")}</div></div>`}).join("");
